var a = el("a", bottom ? "cafe-back cafe-back--bottom" : "cafe-back",
fromMe ? t("bd.backMe", "← 내 정보로") : t("bd.back2", "← 목록으로"));
a.href = fromMe ? "#me" : "#b=" + (board || S.board);
